/**
 * Flags open invoices whose due date has passed as Overdue and writes a run summary.
 *
 * The batch is stateful so the running totals (updated, failed, overdue amount)
 * accumulate across every chunk, regardless of the batch size. Updates are
 * performed with partial-success DML so that a single failing invoice (for
 * example, one rejected by the active validation rule when Customer_Email__c is
 * blank) does not prevent the rest of the chunk from being saved.
 *
 * @example
 * // Run the job with the default batch size
 * Database.executeBatch(new OverdueInvoiceBatch());
 *
 * @example
 * // Run the job with a custom batch size
 * Database.executeBatch(new OverdueInvoiceBatch(), 100);
 */
public with sharing class OverdueInvoiceBatch implements Database.Batchable<SObject>, Database.Stateful {

    /** Status value applied to invoices that are past due. */
    private static final String STATUS_OVERDUE = 'Overdue';

    /** Status value queried by the batch scope. */
    private static final String STATUS_OPEN = 'Open';

    /** Value stored in FB_Job_Summary__c.Job_Name__c. */
    private static final String JOB_NAME = 'OverdueInvoiceBatch';

    // ─── Stateful Tracking ───────────────────────────────────────────────
    private Integer totalUpdated = 0;
    private Integer totalFailed = 0;
    private Decimal totalOverdueAmount = 0;

    // ─── Constructor ─────────────────────────────────────────────────────

    /**
     * No-argument constructor required by Database.executeBatch and by tests
     * that invoke the batch phases directly.
     */
    public OverdueInvoiceBatch() {
    }

    // ─── Batchable Interface ─────────────────────────────────────────────

    /**
     * Defines the scope of the batch: all open invoices that are past due.
     *
     * @param bc The batch context (unused).
     * @return A QueryLocator over the open, past-due invoices.
     */
    public Database.QueryLocator start(Database.BatchableContext bc) {
        return Database.getQueryLocator([
            SELECT Id, Name, Status__c, Due_Date__c, Amount__c, Customer_Email__c
            FROM FB_Invoice__c
            WHERE Status__c = :STATUS_OPEN
            AND Due_Date__c < :Date.today()
        ]);
    }

    /**
     * Flags every invoice in the chunk as Overdue using partial-success DML and
     * accumulates the running totals. Save results are positional, so each
     * result maps back to the invoice at the same index.
     *
     * @param bc The batch context (unused).
     * @param scope The invoices in the current chunk.
     */
    public void execute(Database.BatchableContext bc, List<SObject> scope) {
        if (scope == null || scope.isEmpty()) {
            return;
        }

        List<FB_Invoice__c> invoicesToUpdate = new List<FB_Invoice__c>();
        for (SObject record : scope) {
            FB_Invoice__c invoice = (FB_Invoice__c) record;
            invoice.Status__c = STATUS_OVERDUE;
            invoicesToUpdate.add(invoice);
        }

        List<Database.SaveResult> results = Database.update(invoicesToUpdate, false);
        for (Integer i = 0; i < results.size(); i++) {
            if (results[i].isSuccess()) {
                totalUpdated++;
                Decimal amount = invoicesToUpdate[i].Amount__c;
                totalOverdueAmount += (amount == null ? 0.0 : amount);
            } else {
                totalFailed++;
            }
        }
    }

    /**
     * Inserts exactly one FB_Job_Summary__c capturing the totals for the whole job.
     *
     * @param bc The batch context (unused).
     */
    public void finish(Database.BatchableContext bc) {
        FB_Job_Summary__c summary = new FB_Job_Summary__c(
            Job_Name__c = JOB_NAME,
            Records_Updated__c = totalUpdated,
            Records_Failed__c = totalFailed,
            Overdue_Amount__c = totalOverdueAmount
        );
        insert summary;
    }

    // ─── Convenience ─────────────────────────────────────────────────────

    /**
     * Runs the job with the default batch size.
     *
     * @return The Id of the queued batch job.
     */
    public static Id run() {
        return Database.executeBatch(new OverdueInvoiceBatch());
    }
}
