/**
 * Bulk-safe trigger handler for Contact.
 *
 * The original inline trigger issued one Account SOQL query per Contact in both
 * the before and after contexts, which breached the 100-query governor limit
 * during Data Loader loads. This handler collects every AccountId up front and
 * performs exactly one Account query per context, so an insert or update of up
 * to 200 Contacts consumes at most two SOQL queries and one DML statement.
 *
 * Declared `without sharing` to preserve the original trigger's system-mode
 * behaviour: the previous inline trigger read and updated Account records
 * regardless of the running user's record access.
 */
public without sharing class ContactTriggerHandler {

    /**
     * Populates Account-derived defaults on new Contacts before they are saved.
     *
     * @param newContacts The Contacts being inserted (Trigger.new).
     */
    public void onBeforeInsert(List<Contact> newContacts) {
        applyAccountDefaults(newContacts, true);
    }

    /**
     * Populates Account-derived defaults on updated Contacts before they are saved.
     *
     * @param newContacts The Contacts being updated (Trigger.new).
     */
    public void onBeforeUpdate(List<Contact> newContacts) {
        applyAccountDefaults(newContacts, false);
    }

    /**
     * Copies the first non-blank Contact phone onto an Account that has no phone.
     * When several new Contacts of the same Account carry a phone, the first
     * Contact in trigger order wins, matching the original behaviour.
     *
     * @param newContacts The Contacts that were inserted (Trigger.new).
     */
    public void onAfterInsert(List<Contact> newContacts) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact newContact : newContacts) {
            if (newContact.AccountId != null && String.isNotBlank(newContact.Phone)) {
                accountIds.add(newContact.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsById = new Map<Id, Account>([
            SELECT Id, Phone
            FROM Account
            WHERE Id IN :accountIds
        ]);

        Map<Id, Account> accountsToUpdateById = new Map<Id, Account>();
        for (Contact newContact : newContacts) {
            if (newContact.AccountId == null || String.isBlank(newContact.Phone)) {
                continue;
            }
            Account account = accountsById.get(newContact.AccountId);
            if (account == null) {
                continue;
            }
            // Another Contact in this same trigger already supplied the phone.
            if (accountsToUpdateById.containsKey(newContact.AccountId)) {
                continue;
            }
            // Account already had a phone before this transaction.
            if (String.isNotBlank(account.Phone)) {
                continue;
            }
            account.Phone = newContact.Phone;
            accountsToUpdateById.put(newContact.AccountId, account);
        }

        if (!accountsToUpdateById.isEmpty()) {
            update accountsToUpdateById.values();
        }
    }

    /**
     * Applies Account defaults to Contacts. One query resolves every referenced
     * Account; no query is issued when no Contact has an Account.
     *
     * @param newContacts The Contacts being saved (Trigger.new).
     * @param isInsert    True for before insert, false for before update.
     */
    private void applyAccountDefaults(List<Contact> newContacts, Boolean isInsert) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact newContact : newContacts) {
            if (newContact.AccountId != null) {
                accountIds.add(newContact.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsById = new Map<Id, Account>([
            SELECT Id, BillingCountry, AccountSource
            FROM Account
            WHERE Id IN :accountIds
        ]);

        for (Contact newContact : newContacts) {
            if (newContact.AccountId == null) {
                continue;
            }
            Account account = accountsById.get(newContact.AccountId);
            if (account == null) {
                continue;
            }
            if (String.isBlank(newContact.MailingCountry)) {
                newContact.MailingCountry = account.BillingCountry;
            }
            if (isInsert && String.isBlank(newContact.LeadSource)) {
                newContact.LeadSource = account.AccountSource;
            }
        }
    }
}
