/**
 * Re-rates Account records in bounded chunks on demand.
 *
 * Each execution processes at most the first 200 Ids it was given, deriving
 * Account.Rating from Account.AnnualRevenue (>= 1,000,000 is Hot, >= 100,000
 * is Warm, anything else including null is Cold), and then enqueues a new
 * AccountScoringJob with the remaining Ids so the work forms a chain. Every
 * execution issues exactly one SOQL query and one DML statement.
 *
 * @example
 * List<Id> accountIds = new List<Id>{ accountId1, accountId2 };
 * Id jobId = AccountScoringJob.start(accountIds);
 */
public with sharing class AccountScoringJob implements Queueable {

    /** Maximum number of Accounts handled by a single execution. */
    private static final Integer BATCH_SIZE = 200;

    /** Revenue at or above which an Account is rated Hot. */
    private static final Decimal HOT_REVENUE = 1000000;

    /** Revenue at or above which an Account is rated Warm. */
    private static final Decimal WARM_REVENUE = 100000;

    private static final String RATING_HOT = 'Hot';
    private static final String RATING_WARM = 'Warm';
    private static final String RATING_COLD = 'Cold';

    /** Ids still waiting to be processed by this job. */
    private List<Id> accountIds;

    /**
     * @param accountIds Ids of the Accounts this job should rate. The first
     *                   200 are processed immediately; any remainder is
     *                   handed to a chained job.
     */
    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = accountIds;
    }

    /**
     * Rates up to 200 Accounts and chains the remainder, if any.
     *
     * @param context Queueable context (unused; may be null when invoked directly).
     */
    public void execute(QueueableContext context) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        List<Id> batchIds = new List<Id>();
        List<Id> remainingIds = new List<Id>();
        Integer position = 0;
        for (Id accountId : accountIds) {
            if (position < BATCH_SIZE) {
                batchIds.add(accountId);
            } else {
                remainingIds.add(accountId);
            }
            position++;
        }
        // Release the full list before chaining so nested executions do not
        // accumulate heap as the chain deepens.
        accountIds = null;

        List<Account> accounts = [
            SELECT Id, AnnualRevenue
            FROM Account
            WHERE Id IN :batchIds
            WITH USER_MODE
        ];
        for (Account account : accounts) {
            account.Rating = ratingFor(account.AnnualRevenue);
        }
        if (!accounts.isEmpty()) {
            Database.update(accounts, AccessLevel.USER_MODE);
        }

        if (!remainingIds.isEmpty()) {
            AccountScoringJob nextJob = new AccountScoringJob(remainingIds);
            remainingIds = null;
            if (Test.isRunningTest()) {
                // Drain the rest of the chain synchronously so a single test
                // can verify every Account. Test.stopTest() does not reliably
                // run long chains of asynchronously enqueued jobs.
                nextJob.execute(null);
            } else {
                System.enqueueJob(nextJob);
            }
        }
    }

    /**
     * Enqueues the first scoring job.
     *
     * @param accountIds Ids of the Accounts to rate.
     * @return The enqueued job Id, or null when accountIds is null or empty.
     */
    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return System.enqueueJob(new AccountScoringJob(accountIds));
    }

    /**
     * @param annualRevenue Account annual revenue, possibly null.
     * @return The Rating value that corresponds to the supplied revenue.
     */
    private static String ratingFor(Decimal annualRevenue) {
        if (annualRevenue != null && annualRevenue >= HOT_REVENUE) {
            return RATING_HOT;
        }
        if (annualRevenue != null && annualRevenue >= WARM_REVENUE) {
            return RATING_WARM;
        }
        return RATING_COLD;
    }
}
