/**
 * Scheduled job that purges expired integration log records from
 * FB_Integration_Log__c to keep storage usage under control.
 *
 * Retention policy:
 *  - Records whose Level__c is anything other than ERROR (including blank or
 *    null values) are deleted once they are older than 30 days.
 *  - Records whose Level__c is ERROR are retained for 180 days.
 *
 * @example
 * Id jobId = LogPurgeJob.scheduleNightly();
 */
public with sharing class LogPurgeJob implements Schedulable {

    /** Retention period, in days, for non-ERROR log records. */
    private static final Integer STANDARD_RETENTION_DAYS = 30;

    /** Retention period, in days, for ERROR log records. */
    private static final Integer ERROR_RETENTION_DAYS = 180;

    /** Level__c value that receives the extended retention period. */
    private static final String ERROR_LEVEL = 'ERROR';

    /** Name under which the nightly job is scheduled. */
    private static final String JOB_NAME = 'Log purge (nightly)';

    /** CRON expression for 02:00 every day. */
    private static final String CRON_DAILY_2AM = '0 0 2 * * ?';

    /** Maximum number of records deleted per DML statement. */
    private static final Integer DML_CHUNK_SIZE = 10000;

    /**
     * No-argument constructor required by System.schedule.
     */
    public LogPurgeJob() {
    }

    /**
     * Deletes expired integration logs according to the retention policy.
     * @param context The schedulable context supplied by the platform.
     */
    public void execute(SchedulableContext context) {
        Datetime standardCutoff = Datetime.now().addDays(-STANDARD_RETENTION_DAYS);
        Datetime errorCutoff = Datetime.now().addDays(-ERROR_RETENTION_DAYS);

        List<FB_Integration_Log__c> expiredLogs = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE ((Level__c != :ERROR_LEVEL OR Level__c = null) AND CreatedDate < :standardCutoff)
               OR CreatedDate < :errorCutoff
        ];

        for (Integer index = 0; index < expiredLogs.size(); index += DML_CHUNK_SIZE) {
            Integer endIndex = Math.min(index + DML_CHUNK_SIZE, expiredLogs.size());
            Database.delete(expiredLogs.subList(index, endIndex), false);
        }
    }

    /**
     * Schedules the nightly purge at 02:00.
     * @return The Id of the scheduled job.
     */
    public static Id scheduleNightly() {
        return System.schedule(JOB_NAME, CRON_DAILY_2AM, new LogPurgeJob());
    }
}
