/**
 * Publishes Deal_Stage_Change__e platform events that announce Opportunity stage changes.
 *
 * <p>Deal_Stage_Change__e is defined with Publish After Commit behavior, so the events are
 * emitted only if the enclosing transaction commits. One event is published for each
 * Opportunity passed in, and the returned Database.SaveResult list is index-aligned with
 * the input list.</p>
 */
public with sharing class DealEventPublisher {

    /** Prevents instantiation of this stateless publisher. */
    private DealEventPublisher() {
    }

    /**
     * Publishes one Deal_Stage_Change__e event per Opportunity.
     *
     * @param opportunities The Opportunities whose current stage and amount should be
     *                      broadcast. May be null or empty.
     * @return A List<Database.SaveResult> index-aligned with the input list; index i
     *         describes the publish result for opportunities[i]. Returns an empty list
     *         when the input is null or empty (nothing is published in that case).
     */
    public static List<Database.SaveResult> publishStageChanges(List<Opportunity> opportunities) {
        List<Database.SaveResult> results = new List<Database.SaveResult>();

        if (opportunities == null || opportunities.isEmpty()) {
            return results;
        }

        List<Deal_Stage_Change__e> events = new List<Deal_Stage_Change__e>();
        for (Opportunity opportunity : opportunities) {
            // Opportunity.Id is already the 18-character, case-safe Id in Apex, so it maps
            // directly onto the Text(18) Opportunity_Id__c field with no conversion.
            events.add(new Deal_Stage_Change__e(
                Opportunity_Id__c = opportunity.Id,
                Stage__c = opportunity.StageName,
                Amount__c = opportunity.Amount
            ));
        }

        // Bulk publish: a single EventBus.publish call for the whole batch. The returned
        // SaveResults are in the same order as the events, so they still map 1:1 to the
        // input list and callers can identify exactly which event failed.
        results.addAll(EventBus.publish(events));
        return results;
    }
}
