/**
 * AccountCountrySync
 *
 * When an Account's BillingCountry changes, keeps the MailingCountry of that
 * Account's Contacts in sync:
 *   - Contacts with a blank MailingCountry move to the new BillingCountry.
 *   - Contacts whose MailingCountry equals the Account's PREVIOUS BillingCountry
 *     move to the new BillingCountry.
 *   - Every other Contact (e.g. they work abroad) is left untouched.
 *   - Contacts of Accounts whose BillingCountry did not change are never touched.
 *
 * Bulk safety:
 *   - Exactly one selective SOQL query, scoped to the Accounts that actually
 *     changed in this transaction. The whole Contact table is never loaded.
 *   - No SOQL and no DML inside loops.
 *   - One bulk DML call for all affected Contacts.
 *
 * Sharing:
 *   - `with sharing` prevents a user who can edit an Account from indirectly
 *     modifying Contacts they are not allowed to see. The MDM integration user
 *     (View All Data / Modify All Data) still sees and updates every relevant
 *     Contact, so the sync remains complete for the integration.
 */
public with sharing class AccountCountrySync {

    public static void syncContactMailingCountry(
        List<Account> newAccounts,
        Map<Id, Account> oldAccounts
    ) {
        if (newAccounts == null || newAccounts.isEmpty() || oldAccounts == null) {
            return;
        }

        // 1. Collect only the Accounts whose BillingCountry actually changed,
        //    remembering both the previous and the new value.
        Set<Id> changedAccountIds = new Set<Id>();
        Map<Id, String> previousBillingCountry = new Map<Id, String>();
        Map<Id, String> newBillingCountry = new Map<Id, String>();

        for (Account newAccount : newAccounts) {
            Account oldAccount = oldAccounts.get(newAccount.Id);
            if (oldAccount == null) {
                continue;
            }
            if (newAccount.BillingCountry == oldAccount.BillingCountry) {
                continue; // No change, nothing to sync.
            }
            changedAccountIds.add(newAccount.Id);
            previousBillingCountry.put(newAccount.Id, oldAccount.BillingCountry);
            newBillingCountry.put(newAccount.Id, newAccount.BillingCountry);
        }

        if (changedAccountIds.isEmpty()) {
            return;
        }

        // 2. A single selective query for the Contacts of just those Accounts.
        List<Contact> contactsToUpdate = new List<Contact>();
        for (Contact contact : [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :changedAccountIds
        ]) {
            String oldCountry = previousBillingCountry.get(contact.AccountId);

            // Blank MailingCountry, or it held the Account's previous country.
            if (String.isBlank(contact.MailingCountry)
                || contact.MailingCountry == oldCountry) {
                contact.MailingCountry = newBillingCountry.get(contact.AccountId);
                contactsToUpdate.add(contact);
            }
        }

        if (contactsToUpdate.isEmpty()) {
            return;
        }

        // 3. One bulk DML call. Partial failures are tolerated so a single bad
        //    Contact cannot block the MDM Account update; they are surfaced in
        //    the debug log for monitoring/alerting.
        for (Database.SaveResult result : Database.update(contactsToUpdate, false)) {
            if (!result.isSuccess()) {
                for (Database.Error error : result.getErrors()) {
                    System.debug(
                        LoggingLevel.ERROR,
                        'AccountCountrySync failed to update Contact ' + result.getId()
                            + ': ' + error.getStatusCode() + ' - ' + error.getMessage()
                    );
                }
            }
        }
    }
}
