import { LightningElement, api } from 'lwc';
import favoriteAdd from '@salesforce/label/c.Favorite_Add';
import favoriteRemove from '@salesforce/label/c.Favorite_Remove';

export default class FavoriteToggle extends LightningElement {
    // Internal, optimistic UI state. Kept in sync with the public `favorite`
    // property whenever the parent pushes a new value (e.g. after a refresh).
    favoriteState = false;

    @api
    get favorite() {
        return this.favoriteState;
    }

    set favorite(value) {
        this.favoriteState = value === true || value === 'true';
    }

    get isFavorite() {
        return this.favoriteState;
    }

    get actionLabel() {
        return this.isFavorite ? favoriteRemove : favoriteAdd;
    }

    get ariaPressed() {
        return this.isFavorite ? 'true' : 'false';
    }

    handleClick() {
        this.favoriteState = !this.favoriteState;

        this.dispatchEvent(
            new CustomEvent('favoritechange', {
                detail: { favorite: this.favoriteState },
            })
        );
    }
}
