```javascript
import { LightningElement, api } from 'lwc';

// Module-level counter so that multiple instances on the same page never
// collide on the option ids referenced by aria-activedescendant.
let uidCounter = 0;

export default class StatusListbox extends LightningElement {
    _optionIdPrefix = `status-listbox-${uidCounter++}`;

    _label = '';
    _options = [];
    _value = '';
    _activeIndex = 0;
    _scrollActive = false;

    @api
    get label() {
        return this._label;
    }
    set label(value) {
        this._label = value == null ? '' : value;
    }

    @api
    get options() {
        return this._options;
    }
    set options(value) {
        this._options = Array.isArray(value) ? value : [];
        this._syncActiveToValue();
    }

    @api
    get value() {
        return this._value;
    }
    set value(value) {
        this._value = value == null ? '' : value;
        this._syncActiveToValue();
    }

    // id of the active option, referenced by aria-activedescendant.
    get activeDescendant() {
        if (this._activeIndex < 0 || this._activeIndex >= this._options.length) {
            return null;
        }
        return this._optionId(this._activeIndex);
    }

    // View model consumed by the template.
    get renderedOptions() {
        return this._options.map((option, index) => {
            const isSelected = option.value === this._value;
            return {
                id: this._optionId(index),
                index,
                value: option.value,
                label: option.label,
                isSelected,
                isActive: index === this._activeIndex,
                ariaSelected: isSelected ? 'true' : 'false',
                className: isSelected ? 'slds-item slds-is-selected' : 'slds-item'
            };
        });
    }

    _optionId(index) {
        return `${this._optionIdPrefix}-option-${index}`;
    }

    // Keep the active option aligned with the selection. Falls back to the
    // first option when nothing (or an unknown value) is selected.
    _syncActiveToValue() {
        if (this._options.length === 0) {
            this._activeIndex = 0;
            return;
        }
        const selectedIndex = this._options.findIndex(
            (option) => option.value === this._value
        );
        this._activeIndex = selectedIndex === -1 ? 0 : selectedIndex;
        this._scrollActive = true;
    }

    handleKeydown(event) {
        const count = this._options.length;
        if (count === 0) {
            return;
        }

        switch (event.key) {
            case 'ArrowDown':
                event.preventDefault();
                this._moveActive(Math.min(this._activeIndex + 1, count - 1));
                break;
            case 'ArrowUp':
                event.preventDefault();
                this._moveActive(Math.max(this._activeIndex - 1, 0));
                break;
            case 'Home':
                event.preventDefault();
                this._moveActive(0);
                break;
            case 'End':
                event.preventDefault();
                this._moveActive(count - 1);
                break;
            case 'Enter':
            case ' ':
                event.preventDefault();
                this._selectIndex(this._activeIndex);
                break;
            default:
                // Every other key (notably Tab) keeps its default behaviour.
                break;
        }
    }

    handleOptionClick(event) {
        // aria-activedescendant requires DOM focus to stay on the list.
        const list = this.template.querySelector('[role="listbox"]');
        if (list && typeof list.focus === 'function') {
            list.focus();
        }

        const index = Number(event.currentTarget.dataset.index);
        if (Number.isInteger(index) && index >= 0 && index < this._options.length) {
            this._moveActive(index);
            this._selectIndex(index);
        }
    }

    // Move the active option only; selection is untouched.
    _moveActive(index) {
        if (index < 0 || index >= this._options.length) {
            return;
        }
        this._activeIndex = index;
        this._scrollActive = true;
    }

    _selectIndex(index) {
        const option = this._options[index];
        if (!option) {
            return;
        }
        const wasSelected = option.value === this._value;
        this._activeIndex = index;
        if (wasSelected) {
            return;
        }
        this._value = option.value;
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value: option.value }
            })
        );
    }

    renderedCallback() {
        if (!this._scrollActive) {
            return;
        }
        this._scrollActive = false;
        const activeOption = this.template.querySelector(
            `[data-index="${this._activeIndex}"]`
        );
        if (activeOption && typeof activeOption.scrollIntoView === 'function') {
            activeOption.scrollIntoView({ block: 'nearest' });
        }
    }
}
