```apex
/**
 * Records monthly giving sign-ups from the donation form as Enhanced Recurring
 * Donations (npe03__Recurring_Donation__c).
 *
 * NPSP generates the installment Opportunities from the recurring donation
 * schedule; this service never creates Opportunities itself.
 *
 * The service is bulk-safe: every request is validated before any DML runs, and
 * the whole batch is inserted with a single DML statement (no SOQL is needed).
 */
public with sharing class RecurringGiftService {

    /** Thrown when a gift request is invalid or the recurring donations cannot be created. */
    public class RecurringGiftException extends Exception {}

    /** A single monthly giving sign-up submitted by the donation form. */
    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        /** Day of the month the installment is scheduled on, 1-31. */
        public Integer dayOfMonth;
        public Date startDate;
        /** Number of planned installments; null or 0 means open-ended. */
        public Integer installments;
        /** 'Credit Card', 'ACH' or 'Check'. */
        public String paymentMethod;
    }

    private static final String INSTALLMENT_PERIOD_MONTHLY = 'Monthly';
    private static final Integer MONTHLY_FREQUENCY = 1;
    private static final String STATUS_ACTIVE = 'Active';
    private static final String RECURRING_TYPE_OPEN = 'Open';
    private static final String RECURRING_TYPE_FIXED = 'Fixed';
    private static final String OPEN_ENDED_STATUS_OPEN = 'Open';
    private static final String OPEN_ENDED_STATUS_NONE = 'None';
    private static final String SCHEDULE_TYPE_DIVIDE = 'Divide';
    private static final String SCHEDULE_TYPE_MULTIPLY = 'Multiply';
    private static final Integer OPEN_ENDED_INSTALLMENTS = 1;
    private static final Integer MIN_DAY_OF_MONTH = 1;
    private static final Integer MAX_DAY_OF_MONTH = 31;
    private static final Integer LAST_DAY_OF_MONTH = 31;

    /**
     * Creates one Enhanced Recurring Donation per request.
     *
     * @param requests Monthly giving sign-ups from the form. A null or empty list yields an empty result.
     * @return The new Recurring Donation Ids in the same order as the requests.
     * @throws RecurringGiftException If any request is invalid or the insert fails.
     * @example
     * List<Id> ids = RecurringGiftService.createMonthlyGifts(requests);
     */
    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return new List<Id>();
        }

        // Validate everything up front so a bad request can never partially persist.
        validate(requests);

        List<npe03__Recurring_Donation__c> donations = new List<npe03__Recurring_Donation__c>();
        for (GiftRequest request : requests) {
            donations.add(buildDonation(request));
        }

        try {
            insert donations;
        } catch (DmlException dmlException) {
            throw new RecurringGiftException(
                'Unable to create recurring gifts: ' + dmlException.getMessage(), dmlException);
        }

        List<Id> donationIds = new List<Id>();
        for (npe03__Recurring_Donation__c donation : donations) {
            donationIds.add(donation.Id);
        }
        return donationIds;
    }

    /**
     * Validates every request before any DML.
     *
     * @param requests The requests to validate.
     * @throws RecurringGiftException If a request is null or missing required values.
     */
    private static void validate(List<GiftRequest> requests) {
        for (Integer index = 0; index < requests.size(); index++) {
            GiftRequest request = requests[index];
            if (request == null) {
                throw new RecurringGiftException('Gift request at index ' + index + ' is null.');
            }
            if (request.contactId == null) {
                throw new RecurringGiftException('Gift request at index ' + index + ' is missing a contact.');
            }
            if (request.amount == null || request.amount <= 0) {
                throw new RecurringGiftException('Gift request at index ' + index + ' must have a positive amount.');
            }
            if (request.dayOfMonth == null
                    || request.dayOfMonth < MIN_DAY_OF_MONTH
                    || request.dayOfMonth > MAX_DAY_OF_MONTH) {
                throw new RecurringGiftException(
                    'Gift request at index ' + index + ' must have a day of month between 1 and 31.');
            }
            if (request.startDate == null) {
                throw new RecurringGiftException('Gift request at index ' + index + ' is missing a start date.');
            }
            if (request.installments != null && request.installments < 0) {
                throw new RecurringGiftException(
                    'Gift request at index ' + index + ' cannot have a negative number of installments.');
            }
        }
    }

    /**
     * Maps one validated request to an Enhanced Recurring Donation.
     *
     * @param request A validated gift request.
     * @return The recurring donation ready to insert.
     */
    private static npe03__Recurring_Donation__c buildDonation(GiftRequest request) {
        npe03__Recurring_Donation__c donation = new npe03__Recurring_Donation__c();
        donation.npe03__Contact__c = request.contactId;
        donation.npe03__Amount__c = request.amount;
        donation.npe03__Installment_Period__c = INSTALLMENT_PERIOD_MONTHLY;
        donation.npe03__Date_Established__c = Date.today();
        donation.npsp__InstallmentFrequency__c = MONTHLY_FREQUENCY;
        donation.npsp__StartDate__c = request.startDate;
        donation.npsp__Status__c = STATUS_ACTIVE;
        donation.npsp__PaymentMethod__c = request.paymentMethod;

        // 31 means "last day of the month"; 1-30 are stored as the literal day.
        donation.npsp__Day_of_Month__c = String.valueOf(request.dayOfMonth);
        donation.npsp__Always_Use_Last_Day_Of_Month__c = (request.dayOfMonth == LAST_DAY_OF_MONTH);

        if (request.installments == null || request.installments == 0) {
            donation.npsp__RecurringType__c = RECURRING_TYPE_OPEN;
            donation.npe03__Open_Ended_Status__c = OPEN_ENDED_STATUS_OPEN;
            donation.npe03__Schedule_Type__c = SCHEDULE_TYPE_DIVIDE;
            donation.npe03__Installments__c = OPEN_ENDED_INSTALLMENTS;
        } else {
            donation.npsp__RecurringType__c = RECURRING_TYPE_FIXED;
            donation.npe03__Open_Ended_Status__c = OPEN_ENDED_STATUS_NONE;
            donation.npe03__Schedule_Type__c = SCHEDULE_TYPE_MULTIPLY;
            donation.npe03__Installments__c = request.installments;
        }

        return donation;
    }
}
