```apex
/**
 * FamilyService
 *
 * Links child Contacts to their parent Contacts using NPSP Relationships.
 *
 * The org uses NPSP's default "List Setting" reciprocal method. NPSP
 * automatically creates the reciprocal Relationship when a Relationship
 * record is inserted, so this service only inserts the child -> parent record
 * with type "Parent". NPSP then creates the parent -> child record using the
 * Relationship Lookup for "Parent" (Male: Son, Female: Daughter, Neutral:
 * Child) based on the child's gender.
 *
 * Bulk safe: exactly one SOQL query and one DML statement per invocation,
 * regardless of the number of pairs.
 *
 * Idempotent: a pair is skipped when a Relationship already exists between the
 * two Contacts in either direction, so the import can be re-run safely.
 */
public with sharing class FamilyService {

    private static final String RELATIONSHIP_TYPE_PARENT = 'Parent';
    private static final String RELATIONSHIP_STATUS_CURRENT = 'Current';

    /**
     * Creates a NPSP "Parent" Relationship from each child to its parent.
     * NPSP creates the matching reciprocal (Son/Daughter/Child) automatically.
     *
     * @param parentIdByChildId child Contact Id -> parent Contact Id
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Validate the input and collect every Contact involved.
        Map<Id, Id> validPairs = new Map<Id, Id>();
        Set<Id> contactIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }
            validPairs.put(childId, parentId);
            contactIds.add(childId);
            contactIds.add(parentId);
        }

        if (validPairs.isEmpty()) {
            return;
        }

        // Single SOQL: find every existing Relationship touching any involved
        // Contact so an existing link can be detected in either direction.
        Set<String> existingLinks = new Set<String>();
        for (npe4__Relationship__c relationship : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :contactIds
               OR npe4__RelatedContact__c IN :contactIds
        ]) {
            existingLinks.add(linkKey(relationship.npe4__Contact__c, relationship.npe4__RelatedContact__c));
        }

        // Single DML: one child -> parent "Parent" Relationship per new pair.
        // NPSP creates the reciprocal parent -> child record automatically.
        List<npe4__Relationship__c> relationshipsToInsert = new List<npe4__Relationship__c>();
        for (Id childId : validPairs.keySet()) {
            Id parentId = validPairs.get(childId);
            if (existingLinks.contains(linkKey(childId, parentId))
                    || existingLinks.contains(linkKey(parentId, childId))) {
                continue;
            }
            relationshipsToInsert.add(new npe4__Relationship__c(
                npe4__Contact__c = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c = RELATIONSHIP_TYPE_PARENT,
                npe4__Status__c = RELATIONSHIP_STATUS_CURRENT
            ));
        }

        if (!relationshipsToInsert.isEmpty()) {
            insert relationshipsToInsert;
        }
    }

    // Stable, collision-free key for a directed Contact -> RelatedContact link.
    private static String linkKey(Id contactId, Id relatedContactId) {
        return String.valueOf(contactId) + '|' + String.valueOf(relatedContactId);
    }
}
