File: force-app/main/default/classes/TA_Account_CreateOnboardingTask.cls
```apex
/**
 * Trigger Action: create an onboarding Task for the Account owner when a new
 * Account is created with a customer Type.
 *
 * Registered on the Account after-insert context via the Trigger_Action__mdt
 * record TA_Account_CreateOnboardingTask.
 */
public with sharing class TA_Account_CreateOnboardingTask implements TriggerAction.AfterInsert {
    private static final Set<String> CUSTOMER_TYPES = new Set<String>{
        'Customer - Direct',
        'Customer - Channel'
    };

    public void afterInsert(List<SObject> triggerNew) {
        Date activityDate = Date.today().addDays(7);
        List<Task> tasksToInsert = new List<Task>();

        for (SObject record : triggerNew) {
            Account accountRecord = (Account) record;

            if (CUSTOMER_TYPES.contains(accountRecord.Type)) {
                tasksToInsert.add(
                    new Task(
                        Subject = 'Onboard new customer',
                        WhatId = accountRecord.Id,
                        OwnerId = accountRecord.OwnerId,
                        ActivityDate = activityDate,
                        Status = 'Not Started',
                        Priority = 'Normal'
                    )
                );
            }
        }

        // Single bulk DML, and no DML at all when no Account qualifies.
        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }
}
```

